[
  {
    "name": "林晚",
    "description": "女主，某心理机构派遣的'调查员'，负责核查旧病历。在第七病室逐步发现自己的真实身份",
    "appearance": "28岁女性，齐肩黑色短发被汗水粘在脸颊，皮肤苍白无血色，杏仁眼深陷黑眼圈，嘴唇因恐惧微微发紫",
    "costume": "米白色调查员风衣，下摆沾有不明水渍与灰土；内搭黑色高领毛衣；左手腕系一根断裂的医院腕带，写有'7号床 林'",
    "personality": "理性、警觉、自恃清醒。当现实证据层层瓦解她的认知时，外在的冷静开始碎裂"
  },
  {
    "name": "护士甲（仅声音与剪影）",
    "description": "夜间值班护士，本集仅以走廊广播、远景剪影、半开门缝出现，是林晚认知中第一个'威胁'",
    "appearance": "轮廓模糊，身穿褪色蓝白护士服，走路无声",
    "costume": "褪色蓝白条纹护士服",
    "personality": "机械、重复，象征系统的压迫"
  }
]

[
  {
    "name": "废弃精神病院 · 一楼大厅",
    "description": "黑白棋盘格地砖，多处碎裂；中央服务台布满灰尘与蛛网；天花板日光灯半数破碎，明灭不定",
    "visualStyle": "冷青色月光从破碎玻璃穹顶倾泻，地面反光形成水洼镜面；手持电筒为唯一暖光源，光束扫过扬起细微尘埃"
  },
  {
    "name": "废弃精神病院 · 三楼走廊",
    "description": "狭长走廊，两侧是带铁栅格的病房门；墙皮大片脱落，露出下方黄色旧墙纸；尽头一盏白炽灯闪烁",
    "visualStyle": "强烈单点透视构图，纵深走廊延伸至画面中央消逝点；闪烁的灯造成间歇性阴影，营造焦虑节奏"
  },
  {
    "name": "第七病室",
    "description": "林晚最终进入的目标病房，两张铁架床（仅一张有被褥）、木椅、一张写有'林晚日记'字样的旧床头柜",
    "visualStyle": "完全黑暗，唯靠门缝漏进走廊冷光与手电筒黄色光斑；墙上有人用指甲反复刻出的划痕，疑似字迹"
  },
  {
    "name": "三楼尽头 · 处置室",
    "description": "走廊尽头一扇半掩的铁门，门后有金属器械推车轮廓",
    "visualStyle": "黑暗中只见金属反光与一盏摇摇欲坠的红色指示灯，象征危险与禁区"
  }
]

{
  "scenes": [
    {
      "location": "废弃精神病院 · 一楼大厅",
      "time": "深夜",
      "characters": [
        "林晚"
      ],
      "action": "林晚从冰冷的地面上醒来，挣扎起身，手持电筒环顾四周，确认自己在一座废弃精神病院大厅",
      "dialogue": "（林晚喃喃自语）调查任务……第七病室旧病历核查……",
      "mood": "迷茫、压抑、寂静中充满不安"
    },
    {
      "location": "废弃精神病院 · 三楼走廊",
      "time": "深夜",
      "characters": [
        "林晚",
        "护士甲（远景剪影）"
      ],
      "action": "林晚沿楼梯上行至三楼，走廊尽头出现一个护士剪影，几秒后消失；她决定沿走廊走向第七病室",
      "dialogue": "（广播声，机械女声）夜间巡查时间，请各病房保持安静……",
      "mood": "恐惧初现，空间被未知存在占据"
    },
    {
      "location": "第七病室",
      "time": "深夜",
      "characters": [
        "林晚"
      ],
      "action": "林晚推门进入第七病室，在床头柜发现一本署名'林晚日记'的病友日记，翻开扉页",
      "dialogue": "（林晚低声读出）如果你在读这段话，说明你终于醒了。",
      "mood": "真相入口的恐惧，认知开始松动"
    }
  ]
}
